        : "Add detail and try building again…"
      : "A golden sword that launches mobs into the sky…";

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 180)}px`;
  }, [prompt]);

  const start = async () => {
    if (!canStart) return;
    setBusy(true);
    setError("");
    try {
