                  </div>
                </div>
              );
            case "turn":
              return <AgentTurn key={it.key} turn={it} mod={mod} live={mod.running && it === lastTurn} />;
            case "result":
              return <ResultCard key={it.key} mod={mod} onOpenCode={onOpenCode} />;
            default:
              return null;
          }
        })}
      </div>
      {away && (
        <button className="jump" onClick={jump}>
          Jump to latest
        </button>
      )}
    </div>
  );
}

